import React, { useEffect, useMemo, useRef, useState } from 'react'
import { Form, InputNumber, Modal, Row, Col } from 'antd'
import { GwpModalStyle } from './index.style'
import { connect } from 'react-redux'
import agentActions from '../../../../../redux/agent/actions'
import { fieldTriggerCalculateFees, formItemLayout } from './constant'
import { debounce } from '../../../helpers/utility'
import agentPolicyRedux from 'agentPolicyOps/agentPolicyRedux'

const { updateGwpInfo } = agentActions
const { calculateOfflineFees } = agentPolicyRedux.agentPolicyReduxActions

// Prefer form values over base fee values; keep explicit 0 (do not use ||)
const buildFeesData = (fees = [], formValues = {}) =>
  fees.map((fee) => {
    const formValue = formValues?.[fee?.key]
    return {
      ...fee,
      value: formValue != null ? Number(formValue) : Number(fee?.value ?? 0)
    }
  })

function ModalGWP ({
  showModal,
  onClose,
  policy = {},
  form,
  updateGwpInfoLoader,
  calculateOfflineFeesData,
  calculateOfflineFees,
  updateGwpInfo
}) {
  const [fees, setFees] = useState([])

  const handleCallCalculateOfflineFeesApi = () => {
    const isHardCopyRequired = policy?.hard_copy_required || false
    const hardCopySentTo = policy?.hard_copy_sent_to || ''
    const isCoinsurance = Boolean(
      policy?.is_coinsurance ||
      policy?.request?.is_coinsurance ||
      (Array.isArray(policy?.coinsurance_providers) && policy.coinsurance_providers.length > 0)
    )
    const discount = Number(form.getFieldValue('discount') || 0)
    const basicPremium = Number(form.getFieldValue('basic_premium') || 0)
    const addsOn = Number(form.getFieldValue('add_ons') || 0)
    const subTotal = basicPremium + addsOn

    const payload = {
      sub_total: subTotal,
      discount,
      hard_copy_required: isHardCopyRequired,
      hard_copy_sent_to: hardCopySentTo,
      is_coinsurance: isCoinsurance
    }
    calculateOfflineFees(payload)
  }

  const handleInputChangeDebounce = useRef(
    debounce(() => {
      handleCallCalculateOfflineFeesApi()
    }, 500)
  ).current

  const handleInputChange = (value, name) => {
    const isTriggeredDebounce = fieldTriggerCalculateFees.includes(name)
    if (isTriggeredDebounce) {
      handleInputChangeDebounce()
    }
  }

  const renderFormItem = ({
    name,
    title,
    type,
    placeholder,
    required = true,
    defaultValue = 0,
    disabled = false
  }) => {
    const { getFieldDecorator } = form
    switch (type) {
      case 'number':
        return (
          <Form.Item key={name} label={title}>
            <Row type='flex' align='middle' gutter={8}>
              <Col>
                <span>RP</span>
              </Col>

              <Col style={{ flex: 1 }}>
                {getFieldDecorator(name, {
                  initialValue: Number(defaultValue) || 0,
                  rules: [
                    {
                      required,
                      message: `${title} is required`
                    }
                  ]
                })(
                  <InputNumber
                    style={{ width: '100%' }}
                    min={0}
                    precision={0}
                    disabled={disabled}
                    onChange={(value) => handleInputChange(value, name)}
                    type='number'
                  />
                )}
              </Col>
            </Row>
          </Form.Item>
        )

      default:
        return null
    }
  }

  // Existing
  async function validateForm () {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  const totalPayable = useMemo(() => {
    const feesData = buildFeesData(fees, form.getFieldsValue())
    const totalFees = feesData.reduce(
      (total, fee) => total + Number(fee.value ?? 0),
      0
    )
    const discount = Number(form.getFieldValue('discount') ?? 0)
    const basicPremium = Number(form.getFieldValue('basic_premium') ?? 0)
    const addsOn = Number(form.getFieldValue('add_ons') ?? 0)
    const subTotal = basicPremium + addsOn
    const total = subTotal + totalFees - discount
    return total
  }, [fees, form])

  // Existing
  const handleSubmitData = async (e) => {
    // handle data
    e.preventDefault()
    const valid = await validateForm()

    if (!valid) return
    const formValues = form.getFieldsValue()
    // Build from current form values so the latest input (including 0) is submitted
    const feesData = buildFeesData(fees, formValues)
    const totalFees = feesData.reduce(
      (total, fee) => total + Number(fee.value ?? 0),
      0
    )
    const discount = Number(formValues.discount ?? 0)
    const basicPremium = Number(formValues.basic_premium ?? 0)
    const addsOn = Number(formValues.add_ons ?? 0)
    const submittedTotalPayable = basicPremium + addsOn + totalFees - discount
    const requestBody = {
      referenceId: policy.reference_id,
      basic_premium: formValues.basic_premium,
      add_ons: formValues.add_ons,
      discount: formValues.discount,
      total_sum_insured: formValues.total_sum_insured,
      total_payable: submittedTotalPayable,
      fees: feesData
    }
    updateGwpInfo(requestBody)
  }

  const renderFeesForm = () => {
    return fees.map((fee) => (
      <React.Fragment key={fee.key}>
        {renderFormItem({
          // currently, admin fee is including endorsement fee
          // the simple logic base on the last discussion, handling by FE to show the text.
          title: `${fee.label} ${fee.key === 'admin_fee' ? '(Including Endorsement Fee)' : ''}`,
          required: fee?.is_mandatory || true, // if is_mandatory not exist the default value required will true.
          defaultValue: `${fee?.value}`,
          name: fee.key,
          type: 'number',
          disabled: !fee?.is_editable
        })}
      </React.Fragment>
    ))
  }

  // update fees to initial value from policy detail api.
  useEffect(() => {
    setFees(policy?.fees || [])
  }, [policy])

  // to update the state fees value after calculate request is done.
  useEffect(() => {
    if (!calculateOfflineFeesData?.fees?.length) return

    // Updated form value
    const newForm = {}
    calculateOfflineFeesData.fees.forEach((fee) => {
      newForm[fee.key] = Number(fee.value || 0)
    })
    form.setFieldsValue(newForm)

    // Update fees state
    setFees((prev) =>
      prev.map((fee) => {
        const updated =
          calculateOfflineFeesData.fees.find((x) => x.key === fee.key) || fee

        return {
          ...fee,
          value: updated.value
        }
      })
    )
  }, [calculateOfflineFeesData])

  return (
    <Modal
      visible={showModal}
      onCancel={onClose}
      title='Update Gwp'
      onOk={handleSubmitData}
      okText='Update'
      okButtonProps={{
        style: {
          backgroundColor: '#fac800',
          color: '#000000',
          borderColor: '#fac800'
        }
      }}
      confirmLoading={updateGwpInfoLoader}
      width={620}
    >
      <GwpModalStyle>
        <Form {...formItemLayout}>
          {renderFormItem({
            title: 'Basic Premium',
            type: 'number',
            name: 'basic_premium',
            required: true,
            defaultValue: String(
              policy?.request?.package_detail_response?.basic_premium
            )
          })}
          {renderFormItem({
            title: 'Addons Premium',
            type: 'number',
            name: 'add_ons',
            required: true,
            defaultValue: policy?.payment_detail?.add_ons_premium
              .replace(/,/g, '')
              .replace(/\.\d+$/, '')
          })}
          {renderFormItem({
            title: 'Discount',
            type: 'number',
            name: 'discount',
            required: true,
            defaultValue: policy?.payment_detail?.discount
              .replace(/,/g, '')
              .replace(/\.\d+$/, '')
          })}

          {renderFeesForm()}

          {renderFormItem({
            title: 'Total Sum Insured',
            type: 'number',
            name: 'total_sum_insured',
            required: true,
            defaultValue: policy?.payment_detail?.total_sum_insured
              .replace(/,/g, '')
              .replace(/\.\d+$/, '')
          })}
          <Row type='flex' justify='start' className='margin-10 total'>
            <Col className='text-align-right' span={12}>
              Total Payable:
            </Col>
            <Col span={12}>
              &nbsp;&nbsp;
              <b>
                RP{' '}
                {totalPayable}
              </b>
            </Col>
          </Row>
        </Form>
      </GwpModalStyle>
    </Modal>
  )
}

const WrapperGwpModal = Form.create()(ModalGWP)
export default connect(
  (state) => ({
    updateGwpInfoLoader: state.Loading.UPDATE_GWP_INFO,
    calculateOfflineFeesData: state.AgentProduct.calculateOfflineFeesData
  }),
  {
    updateGwpInfo,
    calculateOfflineFees
  }
)(WrapperGwpModal)
