import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Tag,
  Form
} from 'antd'
import moment from 'moment'
import { get as lodashGet } from 'lodash'
// import { OFFLINE_LANG } from '../OfflineQuotes/lang'
// import { COLORS } from '../../../../constants/colors'

const viewDocument = documentUrl => {
  window.open(documentUrl, '_blank')
}

class PolicyDetailHeaderTable extends React.Component {
  getStatusColor (status) {
    switch (status) {
      case 'ACTIVE':
        return '#2d9600'
      case 'PENDING':
        return '#ffe58f'
      case 'PENDING_EMAIL':
        return '#ffe58f'
      default:
        return ''
    }
  }

  viewQuote = appId => {
    const { history } = this.props
    appId = appId.replace(/-/g, '')
    if (history) {
      history.push('/agent/application/' + appId)
    }
  }

  renderInformation (header, detailData) {
    return (
      <Col span={6}>
        <span>{header}</span>
        <p>{detailData}</p>
      </Col>
    )
  }

  getReasonType (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'Reject'
      case 'CANCELLED': return 'Cancelled'
      default: return ''
    }
  }

  getKeyAccordingToReason (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'rejected'
      case 'CANCELLED': return 'cancelled'
      default: return ''
    }
  }

  render () {
    const { policyDetail, isExtendedWarrantyPolicy } = this.props
    const appId = lodashGet(policyDetail, 'reference_id')
    const bookingDate = lodashGet(policyDetail, 'booking_date')
    const quotationDate = lodashGet(policyDetail, 'quote_created_at')
    const documentDate = lodashGet(policyDetail, 'docs_verified_at')
    const policyCreatedAt = lodashGet(policyDetail, 'created_at', '')
    const policyUpdatedAt = lodashGet(policyDetail, 'updated_at', '')
    const providerUpdatedAt = lodashGet(policyDetail, 'provider_updated_at', '')
    const color = this.getStatusColor(lodashGet(policyDetail, 'policy_state', ''))
    const documentUrl = lodashGet(policyDetail, 'document_url', '')
    const isChildInsurance = !!lodashGet(policyDetail, 'child_insurance.length', 0)
    const documentUrl1 = lodashGet(policyDetail, 'document_url_1', '')
    const inspectionDate = lodashGet(policyDetail, 'binding_date', '')
    const inspectionApprovalDate = lodashGet(policyDetail, 'policy_approved_at', '')
    const policyIssuedDate = lodashGet(policyDetail, 'policy_issuance_date', '')
    return (
      <div>
        <Row className='application-detail-header'>
          <Col span={4}>
            <strong>Application status:</strong>
          </Col>
          <Col span={4} className='application-status-tags'>
            <Tag color={color}>
              {
                lodashGet(policyDetail, 'policy_state') && Object.values(policyDetail).length > 0
                  ? policyDetail.policy_state
                  : '-'
              }
            </Tag>
            {/* {
              (chassisValidation === false) && (
                <Tag color={COLORS.errorRed}>{OFFLINE_LANG.applicationStatusAfterChassisValidation}</Tag>
              )
            } */}
          </Col>
        </Row>
        {
          ['REJECTED', 'CANCELLED'].includes(lodashGet(policyDetail, 'policy_state', '')) && (
            <Row className='application-detail-header'>
              <Col span={4}>
                <b>{`${this.getReasonType(policyDetail?.policy_state)} Reason`}</b>
              </Col>
              <Col className='reject-reason'>
                {lodashGet(policyDetail?.remark_details?.[this.getKeyAccordingToReason(policyDetail?.policy_state)], 'reason')}
              </Col>
            </Row>)
        }
        <Row gutter={32} className='details-data-row'>
          {this.renderInformation('Application Number', lodashGet(policyDetail, 'app_no', '-'))}
          {
            !isChildInsurance && this.renderInformation('Policy Number', (lodashGet(policyDetail, 'insurance_policy_no', '-') || '-'))
          }
          {this.renderInformation('Product ID', lodashGet(policyDetail, 'provider_package.package.product.code', '-'))}
          {
            isChildInsurance
              ? this.renderInformation('Transaction Id', lodashGet(policyDetail, 'payment_detail.quote_app_no', '-'))
              : this.renderInformation(
                '1st Document URL',
                ((!!documentUrl && documentUrl !== 'NA') ? <div className='anchor' onClick={() => viewDocument(documentUrl)}>View File</div> : '-')
              )
          }
        </Row>
        <Row gutter={32} className='details-data-row'>
          {this.renderInformation('Created At', (policyCreatedAt !== ''
            ? moment(policyCreatedAt).format('DD MMMM YYYY')
            : '-'))}
          {this.renderInformation('Provider Name', `${lodashGet(policyDetail, 'policy_type', '-')}-${lodashGet(policyDetail, 'provider_package.provider.name', '-')}`)}
          {this.renderInformation('Package Name', lodashGet(policyDetail, 'provider_package.package.name', '-'))}
          {this.renderInformation('2nd Document URL', ((!!documentUrl1 &&
            documentUrl1 !== 'NA')
            ? <div className='anchor' onClick={() => viewDocument(documentUrl1)}>View File</div>
            : '-'))}

        </Row>
        <Row gutter={32} className='details-data-row'>
          {this.renderInformation('Reference ID', ((!!appId &&
          appId !== 'NA')
            ? <span className='anchor' onClick={() => this.viewQuote(appId)}>{appId}</span>
            : '-'))}
          {this.renderInformation('Insurance Updated At', (providerUpdatedAt
            ? moment(providerUpdatedAt).format('DD MMMM YYYY')
            : '-'))}
          {this.renderInformation('Updated At', (policyUpdatedAt !== ''
            ? moment(policyUpdatedAt).format('DD MMMM YYYY')
            : '-'))}
          {this.renderInformation('Transaction Id', lodashGet(policyDetail, 'payment_detail.quote_app_no', '-'))}
        </Row>
        <Row gutter={32} className='details-data-row'>
          {
            this.renderInformation(
              'Booking Date',
              (bookingDate ? moment(bookingDate).format('DD MMMM YYYY') : '-')
            )
          }
          {
            this.renderInformation(
              'Quotation Created Date',
              (quotationDate ? moment(quotationDate).format('DD MMMM YYYY') : '-')
            )
          }
          {
            this.renderInformation(
              'Document Verified Date',
              (documentDate ? moment(documentDate).format('DD MMMM YYYY') : '-')
            )
          }
          {
            this.renderInformation(
              'Policy Issued Date',
              (policyIssuedDate ? moment(policyIssuedDate).format('DD MMMM YYYY') : '-')
            )
          }
          {
            isExtendedWarrantyPolicy && this.renderInformation(
              'Inspection Date',
              (inspectionDate ? moment(inspectionDate).format('DD MMMM YYYY') : '-')
            )
          }
          {
            isExtendedWarrantyPolicy && this.renderInformation(
              'Inspection Date',
              (inspectionApprovalDate ? moment(inspectionApprovalDate).format('DD MMMM YYYY') : '-')
            )
          }
        </Row>
      </div>
    )
  }
}
const WrappedPolicyDetail = Form.create()(PolicyDetailHeaderTable)
export default connect()(WrappedPolicyDetail)
