import React from 'react'
import { Row, Col, Card } from 'antd'
import { get as lodashGet } from 'lodash'
import { formatMoney } from '../../../../helpers/utility'
import { FLEET_POLICY, MANUAL_ORDER } from '../constants'
import { formatPercent, formatDate, formatMoneyForSummary, getYearCoverageDates } from './helpers'
import {
  SectionHeader,
  TableText,
  SummaryTotalPaymentBox,
  SummaryTotalPaymentLabel,
  SummaryTotalPaymentAmount,
  YearTotalPaymentBox,
  YearTotalPaymentLabel,
  YearTotalPaymentAmount,
  EndorsementValue,
  VerticalFieldContainer,
  VerticalFieldName,
  VerticalFieldValue,
  ColumnHeader,
  YearColumn
} from './policyPaymentDetail.style'

class MultiYearPolicyDetail extends React.Component {

  renderSummarySection (policyDetail, isManualOfflineOrder) {
    const basicInfoData = [
      {
        name: 'Transaction Date',
        value: <strong>{formatDate(lodashGet(policyDetail, 'payment_detail.transaction_date', '-'))}</strong>
      },
      {
        name: 'Coverage Start Date',
        value: <strong>{formatDate(lodashGet(policyDetail, 'payment_detail.proposed_coverage_start', '-'))}</strong>
      },
      {
        name: 'Coverage End Date',
        value: <strong>{formatDate(lodashGet(policyDetail, 'payment_detail.proposed_coverage_end', '-'))}</strong>
      }
    ]

    const premiumDetailsData = [
      {
        name: 'Premium Rate',
        value: <strong>{formatPercent(lodashGet(policyDetail, 'payment_detail.premium_rate', '-'))}</strong>
      },
      {
        name: 'Total Base Premium',
        value: <strong>{formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.base_premium', 0))}</strong>
      },
      {
        name: 'Total Add-On Premium',
        value: <strong>{formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.add_ons_premium', 0))}</strong>,
        hidden: isManualOfflineOrder
      },
      {
        name: 'Total Discount',
        value: <strong>{formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.discount', 0))}</strong>
      },
      {
        name: 'Total Premium (After Endorsement)',
        value: <EndorsementValue><strong>{formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.total_payment', 0))}</strong></EndorsementValue>,
        hidden: !lodashGet(policyDetail, 'endorsement_present', '')
      },
      {
        name: 'Total Gross Premium',
        value: <strong>{formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.gross_premium', 0))}</strong>
      }
    ]

    // FEES NEW APPROACH
    const paymentDetailFees = policyDetail?.payment_detail?.fees || policyDetail?.fees || []
    
    const feesData = paymentDetailFees.map((fee) => {
      const generalInfo = {
        name: fee.label,
        value: <strong>{formatMoneyForSummary(fee?.value || 0)}</strong>
      }

      return fee?.key === "total_endorsement_fee" ? {
        ...generalInfo,
        hidden: !lodashGet(policyDetail, 'endorsement_present', '')
      } : {
        ...generalInfo
      }
    })
    
    const totalPaymentFormatted = formatMoneyForSummary(lodashGet(policyDetail, 'payment_detail.total_payment', 0))

    const allFieldsData = [
      ...basicInfoData,
      ...premiumDetailsData,
      ...feesData
    ].filter(item => !item.hidden)

    const fieldsPerRow = 4
    const maxRows = 4
    const maxFields = maxRows * fieldsPerRow
    const fieldsToDisplay = allFieldsData.slice(0, maxFields)
    
    const fieldRows = []
    for (let i = 0; i < fieldsToDisplay.length; i += fieldsPerRow) {
      fieldRows.push(fieldsToDisplay.slice(i, i + fieldsPerRow))
    }

    return (
      <Card style={{ marginBottom: 24, border: '1px solid #d9d9d9', backgroundColor: '#EBF5FF', borderRadius: '24px' }}>
        <SectionHeader>Summary</SectionHeader>
        <Row gutter={[16, 0]}>
          <Col span={24} style={{ marginBottom: '16px' }}>
            <VerticalFieldContainer>
              <VerticalFieldName>
                <TableText>Transaction Reference</TableText>
              </VerticalFieldName>
              <VerticalFieldValue>
                <TableText><strong>{lodashGet(policyDetail, 'payment_detail.transaction_ref_id', '-')}</strong></TableText>
              </VerticalFieldValue>
            </VerticalFieldContainer>
          </Col>
        </Row>
        <Row gutter={[16, 16]}>
          <Col span={18}>
            {fieldRows.map((rowFields, rowIndex) => (
              <Row key={rowIndex} gutter={[16, 16]}>
                {rowFields.map((item, fieldIndex) => {
                  if (item.hidden) return null
                  return (
                    <Col key={fieldIndex} span={6}>
                      <VerticalFieldContainer>
                        <VerticalFieldName>
                          <TableText>{item.name}</TableText>
                        </VerticalFieldName>
                        <VerticalFieldValue>
                          <TableText>{item.value}</TableText>
                        </VerticalFieldValue>
                      </VerticalFieldContainer>
                    </Col>
                  )
                })}
              </Row>
            ))}
          </Col>
          <Col span={6}>
            <SummaryTotalPaymentBox>
              <SummaryTotalPaymentLabel>Total Payment</SummaryTotalPaymentLabel>
              <SummaryTotalPaymentAmount>{totalPaymentFormatted}</SummaryTotalPaymentAmount>
            </SummaryTotalPaymentBox>
          </Col>
        </Row>
      </Card>
    )
  }

  renderYearSection (year, yearData, policyDetail, isManualOfflineOrder) {
    const basePremium = yearData?.base_premium || {}
    const totalPremium = yearData?.total_premium || {}
    const loadingPremium = yearData?.loading_premium || {}
    const accessoryPremium = yearData?.accessory_premium || {}

    const basicRate = basePremium?.percent || 0
    const loadingRate = loadingPremium?.loading_percent || loadingPremium?.percent || 0

    const basePremiumAmount = basePremium?.premium || 0
    const addOnPremium = accessoryPremium?.premium || 0
    const grossPremium = totalPremium?.premium || 0
    const totalPayment = grossPremium

    const overallStartDate = lodashGet(policyDetail, 'payment_detail.proposed_coverage_start', '-')
    const overallEndDate = lodashGet(policyDetail, 'payment_detail.proposed_coverage_end', '-')
    const yearDates = getYearCoverageDates(year, overallStartDate, overallEndDate)
    const yearBasedPackageTypeMap = lodashGet(policyDetail, 'request.year_based_package_type_map', [])
    const yearPackageData = yearBasedPackageTypeMap.find(item => Number(item.year) === Number(year))
    const packageType = yearPackageData?.package_type || ''
    const formatPackageType = (type) => {
      if (type.includes('comprehensive')) return 'Comprehensive'
      if (type.includes('tlo')) return 'TLO'
      return type
    }
    const formattedPackageType = formatPackageType(packageType)
    
    const protectionData = [
      {
        name: 'Total Sum Insured',
        value: <strong>{formatMoney(totalPremium?.sum_insured || 0)}</strong>
      },
      {
        name: 'Protection Type',
        value: <strong>{formattedPackageType}</strong>
      },
      {
        name: 'Coverage Start Date',
        value: <strong>{yearDates.start}</strong>
      },
      {
        name: 'Coverage End Date',
        value: <strong>{yearDates.end}</strong>
      }
    ]

    const rateData = [
      {
        name: 'Basic Rate',
        value: <strong>{formatPercent(basicRate)}</strong>
      },
      {
        name: 'Loading Rate',
        value: <strong>{formatPercent(loadingRate)}</strong>
      }
    ]

    const premiumData = [
      {
        name: 'Base Premium',
        value: <strong>{formatMoney(basePremiumAmount)}</strong>
      },
      {
        name: 'Add-On Premium',
        value: <strong>{formatMoney(addOnPremium)}</strong>,
        hidden: isManualOfflineOrder
      },
      {
        name: 'Gross Premium',
        value: <strong>{formatMoney(grossPremium)}</strong>
      }
    ].filter(item => !item.hidden)

    const renderVerticalField = (data, prefix = '') => {
      return data.map((item, index) => (
        <VerticalFieldContainer key={`${prefix}_${index}_${year}`}>
          <VerticalFieldName>
            <TableText>{item.name}</TableText>
          </VerticalFieldName>
          <VerticalFieldValue>
            <TableText>{item.value}</TableText>
          </VerticalFieldValue>
        </VerticalFieldContainer>
      ))
    }

    return (
      <Card style={{ marginBottom: 24, border: '1px solid #d9d9d9', borderRadius: '24px' }}>
        <SectionHeader>Year {year}</SectionHeader>
        <Row gutter={[16, 0]} style={{ display: 'flex', alignItems: 'stretch' }}>
          <Col span={6} style={{ display: 'flex', flexDirection: 'column' }}>
            <YearColumn>
              <ColumnHeader>Protection</ColumnHeader>
              {renderVerticalField(protectionData, 'protection')}
            </YearColumn>
          </Col>
          <Col span={6} style={{ display: 'flex', flexDirection: 'column' }}>
            <YearColumn>
              <ColumnHeader>Rate</ColumnHeader>
              {renderVerticalField(rateData, 'rate')}
            </YearColumn>
          </Col>
          <Col span={6} style={{ display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
              <ColumnHeader>Premium</ColumnHeader>
              {renderVerticalField(premiumData, 'premium')}
            </div>
          </Col>
          <Col span={6} style={{ display: 'flex', flexDirection: 'column' }}>
            <YearTotalPaymentBox>
              <YearTotalPaymentLabel>Total Payment</YearTotalPaymentLabel>
              <YearTotalPaymentAmount>{formatMoney(totalPayment)}</YearTotalPaymentAmount>
            </YearTotalPaymentBox>
          </Col>
        </Row>
      </Card>
    )
  }

  render () {
    const { policyDetail, premiumBreakup, yearKeys } = this.props
    const isManualOfflineOrder = [MANUAL_ORDER, FLEET_POLICY].includes(lodashGet(policyDetail, 'request.protection_case', ''))

    return (
      <>
        {this.renderSummarySection(policyDetail, isManualOfflineOrder)}
        {yearKeys.map(year => (
          <Col span={24} key={year}>
            {this.renderYearSection(year, premiumBreakup[year], policyDetail, isManualOfflineOrder)}
          </Col>
        ))}
      </>
    )
  }
}

export default MultiYearPolicyDetail

