import React, { useState } from 'react'
import { connect } from 'react-redux'
import { Row, Col, Form, Table, Tag, Button, Input, InputNumber, DatePicker } from 'antd'
import { get as lodashGet } from 'lodash'
import LayoutContent from '../../../../components/utility/layoutContent'
import { isVNPath } from '../../../../helpers/utility'
import { getPremiumBreakup, checkShowYearWiseBreakup } from './helpers'
import SingleYearPolicyDetail from './SingleYearPolicyDetail'
import MultiYearPolicyDetail from './MultiYearPolicyDetail'

const STATUS_COLOR = { PAID: 'green', NOT_PAID: 'red', PENDING: 'orange' }

function InstallmentTable ({ installments, currencyType, policyId, onUpdateInstallment, onRefresh }) {
  const [rowStates, setRowStates] = useState(() =>
    installments.map((item) => ({
      status: item.status || 'PENDING',
      payment_amount: item.payment_amount || '',
      payment_date: item.payment_date || '',
      payment_remarks: item.payment_remarks || '',
      inputAmount: '',
      inputDate: null,
      inputRemarks: '',
      expanded: false,
      targetStatus: null,
      loading: false,
    }))
  )

  const setField = (index, fields) => {
    setRowStates((prev) => prev.map((r, i) => i === index ? { ...r, ...fields } : r))
  }

  const handleExpand = (index, targetStatus) => {
    setField(index, { expanded: true, targetStatus, inputAmount: '', inputDate: null, inputRemarks: '' })
  }

  const handleConfirm = (index) => {
    const installmentId = installments[index]?.installment_id
    const row = rowStates[index]
    const newStatus = row.targetStatus

    const isPaid = newStatus === 'PAID'
    const paymentDate = isPaid && row.inputDate ? row.inputDate.format('YYYY-MM-DD') : null
    const payload = {
      policyId,
      installment_id: installmentId,
      status: newStatus,
      payment_amount: isPaid ? (row.inputAmount || 0) : 0,
      payment_date: paymentDate,
      payment_remarks: isPaid ? (row.inputRemarks || null) : null,
      onSuccess: () => {
        setField(index, {
          status: newStatus,
          payment_amount: isPaid ? (row.inputAmount || 0) : '',
          payment_date: isPaid ? (paymentDate || '') : '',
          payment_remarks: isPaid ? (row.inputRemarks || '') : '',
          expanded: false,
          loading: false,
        })
        onRefresh(policyId)
      },
    }

    setField(index, { loading: true })
    onUpdateInstallment(payload)
  }

  const handleCancel = (index) => {
    setField(index, { expanded: false, targetStatus: null, inputAmount: '', inputDate: null, inputRemarks: '' })
  }

  const columns = [
    { title: 'Installment No.', dataIndex: 'no', key: 'no', width: 120 },
    { title: 'Installment Premium', dataIndex: 'premium', key: 'premium', width: 160 },
    { title: 'Due Date', dataIndex: 'due_date', key: 'due_date', width: 110 },
    { title: 'Creation Remarks', dataIndex: 'creation_remarks', key: 'creation_remarks', width: 150 },
    {
      title: 'Status',
      key: 'status',
      width: 100,
      render: (_, __, index) => {
        const { status } = rowStates[index] || {}
        return <Tag color={STATUS_COLOR[status] || 'orange'}>{status || 'PENDING'}</Tag>
      }
    },
    {
      title: 'Payment Amount',
      key: 'payment_amount',
      width: 160,
      render: (_, __, index) => {
        const row = rowStates[index] || {}
        if (row.expanded) {
          return (
            <InputNumber
              placeholder='Enter amount'
              style={{ width: '100%' }}
              min={0}
              value={row.inputAmount}
              onChange={(val) => setField(index, { inputAmount: val })}
            />
          )
        }
        return <span>{row.payment_amount ? `${currencyType} ${row.payment_amount}` : '-'}</span>
      }
    },
    {
      title: 'Payment Date',
      key: 'payment_date',
      width: 150,
      render: (_, __, index) => {
        const row = rowStates[index] || {}
        if (row.expanded) {
          return (
            <DatePicker
              placeholder='Select date'
              format='DD-MM-YYYY'
              style={{ width: '100%' }}
              value={row.inputDate}
              onChange={(val) => setField(index, { inputDate: val })}
            />
          )
        }
        return <span>{row.payment_date || '-'}</span>
      }
    },
    {
      title: 'Payment Remarks',
      key: 'payment_remarks',
      width: 160,
      render: (_, __, index) => {
        const row = rowStates[index] || {}
        if (row.expanded) {
          return (
            <Input.TextArea
              rows={2}
              placeholder='Enter payment remarks'
              value={row.inputRemarks}
              onChange={(e) => setField(index, { inputRemarks: e.target.value })}
            />
          )
        }
        return <span>{row.payment_remarks || '-'}</span>
      }
    },
    {
      title: 'Action',
      key: 'action',
      width: 150,
      render: (_, __, index) => {
        const row = rowStates[index] || {}
        if (row.expanded) {
          return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
              <Button size='small' type='primary' loading={row.loading} onClick={() => handleConfirm(index)}>Confirm</Button>
              <Button size='small' disabled={row.loading} onClick={() => handleCancel(index)}>Cancel</Button>
            </div>
          )
        }
        return (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {['PENDING', 'NOT_PAID'].includes(row.status) && (
              <Button size='small' type='primary' ghost onClick={() => handleExpand(index, 'PAID')}>
                Mark as Paid
              </Button>
            )}
            {row.status === 'PENDING' && (
              <Button size='small' danger onClick={() => handleExpand(index, 'NOT_PAID')}>
                Mark as Not Paid
              </Button>
            )}
          </div>
        )
      }
    }
  ]

  const data = installments.map((item, index) => ({
    key: `installment_${index}`,
    no: index + 1,
    premium: item.premium != null ? `${currencyType} ${item.premium}` : '-',
    due_date: item.due_date || '-',
    creation_remarks: item.creation_remarks || '-',
  }))

  return (
    <Table
      pagination={false}
      columns={columns}
      dataSource={data}
      size='small'
      scroll={{ x: 1260 }}
    />
  )
}

class PolicyPaymentDetail extends React.Component {
  constructor (props) {
    super(props)
    this.currencyType = isVNPath() ? 'VND' : 'Rp.'
  }

  getStatusColor (status) {
    switch (status) {
      case 'ACTIVE':
        return '#2d9600'
      case 'PENDING':
        return '#ffe58f'
      case 'PENDING_EMAIL':
        return '#ffe58f'
      default:
        return ''
    }
  }

  renderInformation (header, detailData) {
    return (
      <Col span={6}>
        <span>{header}</span>
        <p>{detailData}</p>
      </Col>
    )
  }

  render () {
    this.currencyType = isVNPath() ? 'VND' : 'Rp'
    const { policyDetail, agentPolicyDetail } = this.props

    const premiumBreakup = getPremiumBreakup(policyDetail, agentPolicyDetail)
    const { showYearWiseBreakup, yearKeys } = checkShowYearWiseBreakup(policyDetail, premiumBreakup)

    const isInstallment = lodashGet(policyDetail, 'payment_detail.payment_information.is_installment', false)
    const installments = isInstallment
      ? lodashGet(policyDetail, 'payment_detail.payment_information.installment_details', [])
      : []

    return (
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title' style={{ marginBottom: '24px' }}>Payment Details</h3>
          {showYearWiseBreakup ? (
            <MultiYearPolicyDetail
              policyDetail={policyDetail}
              premiumBreakup={premiumBreakup}
              yearKeys={yearKeys}
            />
          ) : (
            <SingleYearPolicyDetail
              policyDetail={policyDetail}
              agentPolicyDetail={agentPolicyDetail}
              currencyType={this.currencyType}
            />
          )}
          {isInstallment && installments.length > 0 && (
            <Col span={24} style={{ marginTop: 24 }}>
              <h4 style={{ marginBottom: 12 }}>Installment Details</h4>
              <InstallmentTable
                installments={installments}
                currencyType={this.currencyType}
                policyId={lodashGet(policyDetail, 'reference_id', '')}
                onUpdateInstallment={this.props.updateInstallmentPayment}
                onRefresh={this.props.getAgentPolicyDetails}
              />
            </Col>
          )}
        </Row>
      </LayoutContent>
    )
  }
}
const WrappedPolicyDetail = Form.create()(PolicyPaymentDetail)
export default connect(
  null,
  {
    updateInstallmentPayment: (payload) => ({ type: 'UPDATE_INSTALLMENT_PAYMENT_REQUEST', payload }),
    getAgentPolicyDetails: (payload) => ({ type: 'GET_AGENT_POLICY_DETAILS_REQUEST', payload }),
  }
)(WrappedPolicyDetail)
