import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Table, Form, Modal, Button, message } from 'antd'
import { get as lodashGet } from 'lodash'
import LayoutContent from '../../../../components/utility/layoutContent'
import { isEmpty, isVNPath } from '../../../../helpers/utility'
import { getAddressString } from '../constants'
import PreventCopy from '../components/PreventCopy'
import moment from 'moment'
import { InvoiceModalStyle } from './components/PaymentInformation/index.style'
import { EditObjectDetailFormStyle } from './policy.style'

import PermissionCheckerV2 from '../../../../components/permissionCheckerV2'
import EditFieldModal from './components/EditFieldModal/EditFieldModal'
import { handleValidatePolicyState, canEditField } from './utility'
import { getPolicyDataEditField } from './helpers'
import agentAction from '../../../redux/agent/actions'
import { usePolicyEditItemDataV2 } from './state/hooks/useAgentPolicyState'

const { getAgentInsuranceData } = agentAction
class PolicyDetailInfo extends React.Component {
  state = {
    cancelled_doc_url: '',
    showModal: false,
    isEditableModalVisible: false,
    editableFieldKey: '',
    editableFieldValue: '',
    editableFieldUserInput: '',
    editableFieldUserInputRemarks: '',
    editableFieldError: ''
  }

  getStatusColor (status) {
    switch (status) {
      case 'ACTIVE':
        return '#2d9600'
      case 'PENDING':
        return '#ffe58f'
      case 'PENDING_EMAIL':
        return '#ffe58f'
      default:
        return ''
    }
  }

  renderInformation (header, detailData) {
    return (
      <Col span={6}>
        <span>{header}</span>
        <p>{detailData}</p>
      </Col>
    )
  }

  renderPolicyStateHeading (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'Rejection'
      case 'CANCELLED': return 'Cancellation'
      default: return ''
    }
  }

  getKeyAccordingToRemark (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'rejected'
      case 'CANCELLED': return 'cancelled'
      default: return ''
    }
  }

  getFormattedName (policyState) {
    if (policyState) {
      return policyState.slice(0, 1).toUpperCase() + policyState.slice(1)
    }
  }

  handleModalOnClick (url) {
    this.setState({
      showModal: true,
      cancelled_doc_url: url
    })
  }

  handleModalOnClose () {
    this.setState({
      showModal: false,
      cancelled_doc_url: ''
    })
  }

  handleChangeInput = (val) => {
    if (this.state.editableFieldError) {
      this.setState({ editableFieldError: '' })
    }
    this.setState({ editableFieldUserInput: val })
  }

  handleCloseEditableModal = () => {
    this.setState({
      isEditableModalVisible: false,
      editableFieldKey: '',
      editableFieldValue: '',
      editableFieldUserInput: '',
      editableFieldUserInputRemarks: '',
      editableFieldError: ''
    })
  }

  handleOpenEditableModal = (fieldKey, fieldValueKey) => {
    const { policyDetail, policyDataEdit } = this.props
    const editableField = getPolicyDataEditField(fieldKey, policyDataEdit)

    if (!editableField) {
      return
    }

    this.setState({
      isEditableModalVisible: true,
      editableFieldKey: editableField.data_key,
      editableFieldValue: lodashGet(policyDetail, fieldValueKey, ''),
      editableFieldError: ''
    })
  }

  getPolicyRemarkDetailsData (remarkHeading, keyName) {
    const { policyDetail } = this.props
    const remarkDetails = [
      {
        id: 'rejectedPolicyDetail_1',
        name: <strong>{`${remarkHeading} by`}</strong>,
        value: <span className='anchor'>{lodashGet(policyDetail.remark_details?.[keyName], 'processed_by', '-')}</span>
      },
      {
        id: 'rejectedPolicyDetail_2',
        name: <strong>{`${remarkHeading} at`}</strong>,
        value: moment(lodashGet(policyDetail.remark_details?.[keyName], 'created_at', '-')).format('DD MMMM YYYY HH:mm:ss')
      },
      {
        id: 'rejectedPolicyDetail_3',
        name: <strong>Reason</strong>,
        value: lodashGet(policyDetail.remark_details?.[keyName], 'reason', '-')
      }
    ]
    if (keyName === 'reactivated') {
      return remarkDetails
    }

    if (policyDetail.remark_details?.cancelled && lodashGet(policyDetail.remark_details?.cancelled, 'cancellation_documents').length) {
      const availableDocuments = lodashGet(policyDetail.remark_details?.[keyName], 'cancellation_documents')?.map((url, index) => (
        <div className='object-wrapper' key={index} onClick={() => this.handleModalOnClick(url)}>
          <object
            type='application/pdf'
            data={url}
            width={150}
            height={150}
            aria-label='Cancellation Doc Pdf'
            className='clickable-object'
          />
        </div>
      ))
      remarkDetails.push({
        id: 'rejectedPolicyDetail_4',
        name: <strong>Confirmation Letter from Provider</strong>,
        value: availableDocuments
      })
    }

    return remarkDetails
  }

  renderRemarkDetails = (rejectionType, columns, keyName) => {
    const remarkHeading = this.getFormattedName(keyName)
    return (
      <Row className='rejection-details'>
        <h3 className='policy-title'>{`Policy ${rejectionType} Details`}</h3>
        <Col span={24}>
          <Table
            showHeader={false}
            rowKey={data => data.id}
            columns={columns}
            dataSource={this.getPolicyRemarkDetailsData(remarkHeading, keyName)}
          />
        </Col>
      </Row>
    )
  }

  handleSubmit = async () => {
    const { policyDetail, dispatch, submitEditPolicyFormReq } = this.props
    const { editableFieldKey, editableFieldUserInput, editableFieldUserInputRemarks } = this.state
    const policyId = lodashGet(policyDetail, 'reference_id')
    const userEmail = lodashGet(this.props, 'userEmail', '')
    const policyState = lodashGet(policyDetail, 'policy_state', '')

    try {
      this.setState({ editableFieldError: '' })
      handleValidatePolicyState(policyState)

      // Normalize certain values before sending to backend
      let submitValue = editableFieldUserInput
      if (typeof submitValue === 'string') {
        submitValue = submitValue.trim()
        // Update the UI input so what the user sees matches the submitted value
        if (submitValue !== editableFieldUserInput) {
          this.setState({ editableFieldUserInput: submitValue })
        }
      }

      await submitEditPolicyFormReq({
        policyId,
        body: {
          processed_by: userEmail,
          data: {
            [editableFieldKey]: {
              value: submitValue,
              remarks: editableFieldUserInputRemarks
            }
          }
        }
      })

      dispatch(getAgentInsuranceData({ policyId }))
      this.handleCloseEditableModal()
      message.success('Changes saved successfully')
    } catch (error) {
      // Keep the modal open and show backend validation error (if any)
      const errMsg = (error && (
        (error.response && error.response.data && (error.response.data.message || error.response.data.error)) ||
        error.message
      )) || 'Failed to save changes. Please check your input.'
      this.setState({ editableFieldError: typeof errMsg === 'string' ? errMsg : JSON.stringify(errMsg) })
      // also surface a toast for visibility
      message.error(typeof errMsg === 'string' ? errMsg : 'Failed to save changes. Please check your input.')
    }
  }

  render () {
    const { policyDetail, agentPolicyDetails, isTravelProtection, productId, policyDataEdit } = this.props
    let branchAddress = ''
    let customerAddr = ''
    if (!isEmpty(lodashGet(policyDetail, 'customer_address', ''))) {
      if (lodashGet(policyDetail, 'customer_address.city_name', '')) {
        customerAddr = `${lodashGet(policyDetail, 'customer_address.address')}, ${lodashGet(policyDetail, 'customer_address.city_name')} ${lodashGet(policyDetail, 'customer_address.postal_code')}, ${lodashGet(policyDetail, 'customer_address.province_name')}`
      } else {
        customerAddr = lodashGet(policyDetail, 'customer_address.address')
      }
    }
    if (!isEmpty(lodashGet(policyDetail, 'provider_branch', ''))) {
      const addr = getAddressString(
        (policyDetail?.provider_branch?.location && (policyDetail?.provider_branch?.location !== null))
          ? policyDetail?.provider_branch?.location
          : {}
      )
      branchAddress = `${lodashGet(policyDetail, 'provider_branch.name', '')}`
      if (addr) {
        branchAddress = `${branchAddress} - ${addr}`
      }
    }

    const policyState = lodashGet(policyDetail, 'policy_state', '')
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value',
        render: (text, record) => {
          const editable = record.fieldKey && canEditField(record.fieldKey, policyState, productId, policyDataEdit)
          return (
            <EditObjectDetailFormStyle>
              {text}
              {editable && (
                <PermissionCheckerV2 requiredPermission='ops.edit_agency_object_detail'>
                  <Button
                    icon='edit'
                    onClick={() => this.handleOpenEditableModal(record.fieldKey, record.fieldValueKey)}
                    style={{ marginLeft: 8 }}
                  >
                    Edit
                  </Button>
                </PermissionCheckerV2>
              )}
            </EditObjectDetailFormStyle>
          )
        }
      }
    ]
    const usePayLater = lodashGet(policyDetail, 'request.use_pay_later', false)
    const providerPPWDate = lodashGet(policyDetail, 'request.provider_ppw_datetime', '')
    const agentPPWDate = lodashGet(agentPolicyDetails, 'pay_later_expired_at', '')
    const getKTPNumber = () => {
      if (isTravelProtection) return lodashGet(policyDetail, 'request.customer_data.main_traveller.insured_id', 0)
      return lodashGet(policyDetail, 'request.ktp_no', '-')
    }
    const columnPolicyDetailsReq = [
      {
        id: 'policyDetail_1',
        name: <strong>{isTravelProtection ? 'Policy holder ' : 'Name'}</strong>,
        value: lodashGet(policyDetail, 'name', '-'),
        fieldKey: 'customer_name',
        fieldValueKey: 'name'
      }, {
        id: 'policyDetail_2',
        name: <strong>{isVNPath() ? 'ID Number' : 'Nomor KTP'}</strong>,
        value: getKTPNumber(),
        fieldKey: 'ktp_no',
        fieldValueKey: isTravelProtection ? 'request.customer_data.main_traveller.insured_id' : 'request.ktp_no'
      }, {
        id: 'policyDetail_3',
        name: <strong>Email</strong>,
        value: lodashGet(policyDetail, 'email', '-')
      }, {
        id: 'policyDetail_4',
        name: <strong>Phone Number</strong>,
        value: lodashGet(policyDetail, 'mobile_no', '-')
      },
      {
        id: 'policyDetail_5',
        name: <strong>Coverage Period</strong>,
        value: `${lodashGet(policyDetail, 'payment_detail.proposed_coverage_start', '-')} to ${lodashGet(policyDetail, 'payment_detail.proposed_coverage_end', '-')}`
      },
      {
        id: 'policyDetail_6',
        name: <strong>Pay Later</strong>,
        value: usePayLater ? 'Yes' : 'No'
      },
      ...(
        usePayLater
          ? [
              {
                id: 'policyDetail_7',
                name: <strong>Payment Due Date by Mitra</strong>,
                value: agentPPWDate ? moment(agentPPWDate).format('DD MMMM YYYY') : '-'
              },
              {
                id: 'policyDetail_8',
                name: <strong>Payment Due Date to Provider</strong>,
                value: providerPPWDate ? moment(providerPPWDate).format('DD MMMM YYYY') : '-'
              }
            ]
          : [])
    ]
    if (customerAddr) {
      columnPolicyDetailsReq.push({
        id: 'policyDetail_9',
        name: <strong> Customer Address </strong>,
        value: customerAddr
      })
    }
    columnPolicyDetailsReq.push({
      id: 'policyDetail_10',
      name: <strong> Policy Issuance To </strong>,
      value: branchAddress
    })
    if (lodashGet(policyDetail, 'request.registration_number', '')) {
      columnPolicyDetailsReq.push({
        id: 'policyDetail_11',
        name: <strong> Registration Number(IMO) </strong>,
        value: lodashGet(policyDetail, 'request.registration_number', '-')
      })
    }

    if (isTravelProtection) {
      columnPolicyDetailsReq.push({
        id: 'insured_type',
        name: <strong> Insured Id Type </strong>,
        value: lodashGet(policyDetail, 'request.customer_data.insured_id_type', '-')
      })
    }

    return (
      <PreventCopy>
        <LayoutContent className='details-info-container policy-detail-card'>
          <Row>
            <h3 className='policy-title'>Policy Details</h3>
            <Col span={24}>
              <Table
                pagination={{
                  pageSize: 100
                }}
                showHeader={false}
                rowKey={data => data.id}
                columns={columns}
                dataSource={columnPolicyDetailsReq}
              />
            </Col>
          </Row>
          {
            !isEmpty(policyDetail.remark_details) &&
              <>
                {
                  policyDetail.remark_details?.reactivated &&
                    this.renderRemarkDetails('Reactivation', columns, 'reactivated')
                }
                {
                  policyDetail.remark_details?.cancelled &&
                    this.renderRemarkDetails('Cancellation', columns, 'cancelled')
                }
                {
                  policyDetail.remark_details?.rejected &&
                    this.renderRemarkDetails('Rejection', columns, 'rejected')
                }
              </>
          }
          <Modal
            visible={this.state.showModal}
            onCancel={() => this.handleModalOnClose()}
            style={{ top: 0 }}
            width='100vw'
            footer={null}
          >
            <InvoiceModalStyle>
              <Row type='flex' justify='center'>
                <iframe src={this.state.cancelled_doc_url} title='Confitmation Letter' className='invoice-iframe' />
              </Row>
            </InvoiceModalStyle>
          </Modal>
          <EditFieldModal
            visible={this.state.isEditableModalVisible}
            title={`Edit ${this.state.editableFieldKey}`}
            editableFieldKey={this.state.editableFieldKey}
            editableFieldValue={this.state.editableFieldValue}
            editableFieldUserInput={this.state.editableFieldUserInput}
            editableFieldUserInputRemarks={this.state.editableFieldUserInputRemarks}
            fieldError={this.state.editableFieldError}
            onClose={this.handleCloseEditableModal}
            onChangeInput={this.handleChangeInput}
            onChangeRemarks={(val) => this.setState({ editableFieldUserInputRemarks: val })}
            onSubmit={this.handleSubmit}
          />
        </LayoutContent>
      </PreventCopy>
    )
  }
}

const mapStateToProps = (state) => ({
  user: state.Auth.user
})

const ConnectedPolicyDetailInfo = connect(mapStateToProps)(Form.create()(PolicyDetailInfo))

const PolicyDetailInfoWithHook = (props) => {
  const [, submitEditPolicyFormReq] = usePolicyEditItemDataV2()
  return <ConnectedPolicyDetailInfo {...props} submitEditPolicyFormReq={submitEditPolicyFormReq} />
}

export default PolicyDetailInfoWithHook
