import React from 'react'
import { Col, Table } from 'antd'
import { get as lodashGet } from 'lodash'
import { FLEET_POLICY, MANUAL_ORDER } from '../constants'

class SingleYearPolicyDetail extends React.Component {
  render () {
    const { policyDetail, agentPolicyDetail } = this.props
    const isManualOfflineOrder = [MANUAL_ORDER, FLEET_POLICY].includes(lodashGet(policyDetail, 'request.protection_case', ''))
    const currencyType = this.props.currencyType || 'Rp'

    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value'
      }
    ]

    // FEES NEW APPROACH
    const paymentDetailFees = policyDetail?.payment_detail?.fees || policyDetail?.fees || []

    const feesColumns = paymentDetailFees?.map((fee) => {
      const currencyTypeLabel = fee?.currency === "IDR" ? "Rp" : currencyType
      return {
        name: <strong>{fee?.label}</strong>,
        value: `${currencyTypeLabel} ${fee?.value}`
      }
    })
    const columnPolicyDetailsReq = [
      {
        name: <strong>Txn Ref</strong>,
        value: lodashGet(policyDetail, 'payment_detail.transaction_ref_id', '-')
      }, {
        name: <strong>Txn Date</strong>,
        value: lodashGet(policyDetail, 'payment_detail.transaction_date', '-')
      }, {
        name: <strong>Proposed Coverage Start Date</strong>,
        value: lodashGet(policyDetail, 'payment_detail.proposed_coverage_start', '-')
      },
      {
        name: <strong>Proposed Coverage End Date</strong>,
        value: lodashGet(policyDetail, 'payment_detail.proposed_coverage_end', '-')
      },
      {
        name: <strong>Total Sum Insured</strong>,
        value: <strong>{currencyType} {lodashGet(policyDetail, 'payment_detail.total_sum_insured', '-')}</strong>
      },
      {
        name: <strong>Premium Rate</strong>,
        value: `${lodashGet(policyDetail, 'payment_detail.premium_rate', '-')}%`
      },
      {
        name: <strong>Base Premium</strong>,
        value: `${currencyType} ${lodashGet(policyDetail, 'payment_detail.base_premium', '-')}`
      },
      {
        name: <strong>Addons Premium</strong>,
        value: `${currencyType} ${lodashGet(policyDetail, 'payment_detail.add_ons_premium', '-')}`,
        hidden: isManualOfflineOrder
      },
      {
        name: <a href='#endorsement_detail'><strong>Premium Changes after endorsement (exclude discount)</strong></a>,
        value: <a href='#endorsement_detail'>{`${currencyType} ${lodashGet(policyDetail, 'payment_detail.total_premium_delta', '-')}`}</a>,
        hidden: !lodashGet(policyDetail, 'endorsement_present', '')
      },
      {
        name: <a href='#endorsement_detail'><strong>Endorsement Fee</strong></a>,
        value: <a href='#endorsement_detail'>{`${currencyType} ${lodashGet(policyDetail, 'payment_detail.total_endorsement_fee', '-')}`}</a>,
        hidden: !lodashGet(policyDetail, 'endorsement_present', '')
      },
      {
        name: <strong>Fleet Discount</strong>,
        value: <strong>Rp. {lodashGet(policyDetail, 'fleet_discount', '-')}</strong>,
        hidden: !lodashGet(policyDetail, 'fleet_discount', '')
      },
      {
        name: <strong>Gross Premium</strong>,
        value: <strong>{currencyType} {lodashGet(policyDetail, 'payment_detail.gross_premium', '-')}</strong>
      }, {
        name: <strong>Discount</strong>,
        value: `${currencyType} ${lodashGet(policyDetail, 'payment_detail.discount', '-')}`
      },
      {
        name: <strong>Net Premium</strong>,
        value: <strong>{currencyType} {lodashGet(policyDetail, 'payment_detail.net_premium', '-')}</strong>,
        hidden: isManualOfflineOrder
      },
      ...feesColumns,
      {
        name: <strong>Total Payment</strong>,
        value: <strong>{currencyType} {lodashGet(policyDetail, 'payment_detail.total_payment', '-')}</strong>
      },
      {
        name: <strong>Invisible Discount</strong>,
        value: <strong>{currencyType} {
          (() => {
            try {
              const extraData = agentPolicyDetail?.policy_extra_data
              if (extraData && typeof extraData === 'string' && extraData.trim()) {
                const parsed = JSON.parse(extraData)
                return parsed?.discount || '-'
              }
              return '-'
            } catch (e) {
              return '-'
            }
          })()
        }</strong>,
        hidden: !(agentPolicyDetail?.policy_extra_data && typeof agentPolicyDetail.policy_extra_data === 'string' && agentPolicyDetail.policy_extra_data.includes('discount'))
      }
    ].filter(item => !item.hidden)

    return (
      <Col span={24}>
        <Table
          pagination={{
            pageSize: 100
          }}
          showHeader={false}
          columns={columns}
          dataSource={columnPolicyDetailsReq}
        />
      </Col>
    )
  }
}

export default SingleYearPolicyDetail

