            getPolicyDetailLoader || updateHardCopyLoader || uploadPolicyFileLoading ||
            updatePolicyDocumentLoading || cancelUnpaidPolicyLoader || uploadCancellationDocumentLoader || editImageTimestampLoader ||
            activatePolicyWithOutDetailsLoading
