import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Table } from 'antd'
import { find, get } from 'lodash'
import { renderAgentTags } from 'opsModule/helpers'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import isVNPath from '../../../../../../helpers/isVNPath'

class AgentDetailsTable extends Component {
  static propTypes = {
    agent: PropTypes.object
  };

  constructor (props) {
    super(props)
    const { agent } = props
    this.isStaffAccount = find(agent.agent_tags, { tag_type: 'staff' })
  }

  viewAgent = (agentRef) => {
    const { history } = this.props
    if (history) {
      history.push(
        isVNPath()
          ? `/agent/vn/${agentRef}/detail`
          : `/agent/${agentRef}/detail`
      )
    }
  };

  getAgentType = (agent) => {
    if (this.isStaffAccount) {
      return 'Staff Aggregator'
    }
    return get(agent, 'referral_code', '-').toLowerCase() === 'gojek'
      ? 'Gojek Driver'
      : 'Mitra'
  };

  getAgentColumnsData = () => {
    const { agent } = this.props
    const agentRef = get(agent, 'agent_ref', '')
    return [
      {
        id: 'agent_1',
        name: <strong>Mitra Name</strong>,
        value: (
          <span className='anchor' onClick={() => this.viewAgent(agentRef)}>
            {this.isStaffAccount ? 'Staff ' : ''}
            {get(agent, 'name', '-')}
            {renderAgentTags(agent)}
          </span>
        )
      },
      {
        id: 'agent_2',
        name: <strong>Mitra Email</strong>,
        value: get(agent, 'email', '-')
      },
      {
        id: 'agent_3',
        name: <strong>Mitra Phone Number</strong>,
        value: get(agent, 'phone_no', '-')
      },
      {
        id: 'agent_4',
        name: <strong>Mitra Code</strong>,
        value: get(agent, 'agent_code', '-')
      },
      {
        id: 'agent_5',
        name: <strong>Mitra Type</strong>,
        value: this.getAgentType(agent)
      },
      {
        id: 'agent_6',
        name: <strong>Parent Mitra Name</strong>,
        value: get(agent, 'parent_name', '-')
      },
      {
        id: 'agent_7',
        name: <strong>Parent Mitra Code</strong>,
        value: get(agent, 'parent_code', '-')
      },
      {
        id: 'agent_8',
        name: <strong>PIC Marketing</strong>,
        value: get(agent, 'pic_marketing.marketing_pic', '-')
      }
    ]
  };

  render () {
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      },
      {
        dataIndex: 'value'
      }
    ]

    return (
      <LayoutContentStyle className='details-info-container policy-detail-card'>
        <div>
          <h3 className='policy-title'>Mitra Details</h3>
          <Table
            pagination={{
              pageSize: 100
            }}
            rowKey={(data) => data.id}
            showHeader={false}
            columns={columns}
            dataSource={this.getAgentColumnsData()}
          />
        </div>
      </LayoutContentStyle>
    )
  }
}

export default AgentDetailsTable
